#####Shipped datasets agree with the shipped model and code#####

## The bundled datasets are generated by data-raw/data_sad_raw.R. These tests
## fail when a change to inst/models/pkmodel.cpp or df_forest_preprocess()
## leaves them stale; the fix is to re-run that script, not to edit the test.
regen_hint <- "regenerate the datasets with data-raw/data_sad_raw.R"

test_that("data_sad_pkfit PRED matches the bundled pkmodel", {
  skip_on_cran()
  obs <- dplyr::select(data_sad_pkfit, -PRED, -IPRED)
  refit <- suppressMessages(df_mrgsim_addpred(obs, model_mread_load("pkmodel")))
  expect_equal(refit$PRED, data_sad_pkfit$PRED, tolerance = 1e-6,
               label = paste("PRED recomputed from pkmodel;", regen_hint))
})

test_that("data_sad_pkforest is df_forest_preprocess() of data_sad_pkforest_sim", {
  ## Arguments mirror data-raw/data_sad_raw.R (data_sad_pkforest block).
  rebuilt <- df_forest_preprocess(
    data_sad_pkforest_sim,
    metric_vars = c("CMAX", "CMIN", "AUC", "CAVG"),
    cov_vars = c("FOOD", "WTBL"),
    cov_val_ref = c(FOOD = 0, WTBL = 70),
    cov_labels = list(
      FOOD = c("0" = "Fasted", "1" = "Fed"),
      WTBL = function(x) paste(x, "kg")
    )
  )
  expect_identical(rebuilt, data_sad_pkforest,
                   label = paste("df_forest_preprocess() output;", regen_hint))
})

test_that("data_sad_pkfit carries data_sad's PK records", {
  ## Matched on the LINE record key: the two order dose and observation
  ## records at a shared time differently.
  cols <- c("LINE", "ID", "TIME", "EVID", "MDV", "ODV")
  by_line <- function(d) as.data.frame(dplyr::arrange(d, LINE)[cols])
  expect_equal(by_line(data_sad_pkfit), by_line(dplyr::filter(data_sad, CMT != 3)))
})
